-- 050: Bytter ut innholdet i to av de tre inspirasjonsartiklene fra 024.
-- "En uke i Albir" blir en generell Costa Blanca-destinasjonsartikkel,
-- "Hva skjer egentlig på en coaching-økt med André?" blir en pitch for
-- klubbturer. Den tredje artikkelen ("Derfor elsker vi Costa Blanca")
-- røres ikke. Slug endres siden temaet er helt nytt.

update public.articles
set
  slug = 'costa-blanca-spanias-beste-padeldestinasjon',
  title = 'Costa Blanca: Spanias beste padeldestinasjon',
  excerpt = 'Sol, padelglede og små kystbyer. Vi forklarer hvorfor Costa Blanca er blitt vårt favorittsted for padelreiser.',
  category = 'Destinasjon',
  meta_description = 'Oppdag hvorfor Costa Blanca er Spanias beste padeldestinasjon — padelkultur, solrike dager og koselige kystbyer som Altea og Albir.',
  content = $json${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Det er ikke uten grunn at vi har forelsket oss i Costa Blanca. Med solrike dager, flotte padelanlegg og en padelkultur som lever fra morgen til kveld, er dette etter vår mening et av de aller beste stedene å reise for deg som elsker padel."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Her er padel mer enn bare en sport"}]},{"type":"paragraph","content":[{"type":"text","text":"I Spania er padel en naturlig del av hverdagen. Banene fylles av både lokale spillere og tilreisende, og det er nesten alltid liv rundt anleggene. Folk møtes for å spille, men blir gjerne værende etter kampen for å ta noe kaldt å drikke, se på andre kamper eller slå av en prat."}]},{"type":"paragraph","content":[{"type":"text","text":"Det er noe med den avslappede stemningen som gjør padel ekstra gøy her nede. Du trenger ikke spille på et høyt nivå for å føle deg som en del av miljøet. Det handler like mye om spilleglede og menneskene rundt deg som om resultatet på banen."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Sol, padel og små kystbyer"}]},{"type":"paragraph","content":[{"type":"text","text":"En av de største fordelene med Costa Blanca er klimaet. Med milde vintre og mange soldager er det gode muligheter for å spille utendørs store deler av året. Og når du ikke står på banen, er det mye annet å glede seg over."}]},{"type":"paragraph","content":[{"type":"text","text":"Ta turen til Altea og rusle gjennom de hvite gatene i gamlebyen, nyt en lang lunsj ved sjøen i Albir eller finn en hyggelig restaurant der kvelden gjerne varer litt lenger enn planlagt. Her ligger alt til rette for å kombinere aktive dager med skikkelig feriefølelse."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Opplev Costa Blanca med FERA"}]},{"type":"paragraph","content":[{"type":"text","text":"Vi kjenner området godt og har valgt Costa Blanca som utgangspunkt for padelreisene våre. Her kan vi kombinere gode hoteller, flotte padelanlegg og opplevelser vi selv setter pris på."}]},{"type":"paragraph","content":[{"type":"text","text":"Enten du reiser alene, med venner eller sammen med klubben, ønsker vi å gi deg en tur med mye padel, gode opplevelser og nye bekjentskap."}]},{"type":"paragraph","content":[{"type":"text","text":"Og kanskje er det nettopp her du finner din neste faste padelgjeng."}]}]}$json$::jsonb
where slug = 'en-uke-i-albir';

update public.articles
set
  slug = 'ta-klubben-med-til-solfylte-spania',
  title = 'Ta klubben med til solfylte Spania',
  excerpt = 'En klubbtur til Costa Blanca gir padel, sol og gode minner sammen med klubben. Vi tar oss av organiseringen på destinasjonen.',
  category = 'Tips',
  meta_description = 'Planlegg en klubbtur til Costa Blanca med FERA. Vi organiserer hotell, baner og opplegg — du samler gjengen.',
  content = $json${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hva med å bytte ut den vanlige treningsuka hjemme med noen dager fylt med padel, sol og hyggelige kvelder sammen? En klubbtur til Spania er en fin anledning til å utvikle spillet, bli bedre kjent og skape minner utenfor de faste treningstidene."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Mer enn bare padel"}]},{"type":"paragraph","content":[{"type":"text","text":"Det er noe eget med å reise på tur sammen med klubben. Man får tid til å bli kjent på en annen måte, spille med nye makkere og dele opplevelser som det sjelden blir plass til i en travel hverdag."}]},{"type":"paragraph","content":[{"type":"text","text":"På Costa Blanca kan dere starte dagen med padel, ta en lang lunsj i sola og samles til middag på en hyggelig restaurant om kvelden. Kanskje blir det en intern turnering, noen ekstra timer med trener eller bare masse sosial spilling. Det viktigste er at alle får en tur de har glede av, uansett nivå."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Vi gjør det enkelt å reise sammen"}]},{"type":"paragraph","content":[{"type":"text","text":"Å arrangere en klubbtur kan fort bli mye jobb. Flytider skal koordineres, hotell bestilles og baner reserveres. Hos FERA slipper dere å organisere alt selv."}]},{"type":"paragraph","content":[{"type":"text","text":"Vi har satt sammen reiseopplegg med gode hoteller, flotte padelanlegg og muligheter for både trening og sosial spilling. Vi tar oss av organiseringen på destinasjonen og kan gjøre enkelte tilpasninger etter klubbens behov og ønsker."}]},{"type":"paragraph","content":[{"type":"text","text":"På flere av hotelloppleggene våre ligger padelbanene under 200 meter fra hotellet. Det betyr mindre tid på transport og mer tid til det dere faktisk har reist for."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"En tur som styrker klubbmiljøet"}]},{"type":"paragraph","content":[{"type":"text","text":"Noe av det beste med klubbturer er det som skjer utenfor banen. Samtalene over middagsbordet, latteren etter en jevn kamp og de nye vennskapene som oppstår når man tilbringer noen dager sammen."}]},{"type":"paragraph","content":[{"type":"text","text":"Vi ønsker at dere skal komme hjem med gode minner, ny spilleglede og et enda sterkere fellesskap i klubben."}]},{"type":"paragraph","content":[{"type":"text","text":"Samle gjengen, så hjelper vi dere med å finne en padelreise som passer klubben deres.","marks":[{"type":"bold"}]}]}]}$json$::jsonb
where slug = 'coaching-med-andre';
